Object.assign(terms, Object.fromEntries(glossaryEntries.map(([term, definition]) => [term, definition])));

function glossaryPage() {
  const escape = text => String(text).replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
  const group = term => /^\d/.test(term) ? '0–9' : term[0].toUpperCase();
  const groups = [...new Set(glossaryEntries.map(([term]) => group(term)))];
  const letterId = letter => `heading-letter-${letter === '0–9' ? 'numbers' : letter.toLowerCase()}`;
  let previous;
  const entries = glossaryEntries.map(([term, definition, chapterId]) => {
    const letter = group(term);
    const divider = previous === letter ? '' : `<h2 id="${letterId(letter)}">${letter}</h2>`;
    previous = letter;
    const id = textbookHeadingId(term);
    const chapter = chapters.find(item => item.id === chapterId);
    const title = chapter?.title || 'Making decisions with selection';
    const unit = chapter?.unit || 1;
    return `${divider}<section class="glossary-entry"><h3 id="${id}"><a href="#glossary/${encodeURIComponent(id)}">${escape(term)}</a></h3><p>${escape(definition)}</p><p class="glossary-context"><a href="#${chapterId}">Unit ${unit}: ${escape(title)} →</a></p></section>`;
  }).join('');
  return `<article class="glossary"><p class="eyebrow">REFERENCE / UNITS 1–4</p><h1>Computer science glossary.</h1><p class="lede">${glossaryEntries.length} terms for programming, networks, databases and cyber security. Choose a letter, search for a topic, or follow a term’s chapter link for examples.</p><p>Each term heading is a direct link you can bookmark or share.</p><nav class="glossary-alphabet no-print" aria-label="Glossary letters">${groups.map(letter => `<a href="#glossary/${letterId(letter)}" aria-label="Glossary letter ${letter}">${letter}</a>`).join('')}</nav>${entries}<h2>References and review</h2><p>Original classroom summaries for this working edition; teacher review remains pending. Use the linked chapters for context and the <a href="${source}">SCSA course documents</a> for curriculum requirements.</p><p>Technical references: <a href="https://docs.python.org/3/glossary.html">Python glossary</a>, <a href="https://www.sqlite.org/foreignkeys.html">SQLite foreign keys</a>, <a href="https://www.sqlite.org/lang_select.html">SQLite SELECT</a>, <a href="https://csrc.nist.gov/glossary/term/encryption">NIST encryption</a> and <a href="https://csrc.nist.gov/glossary/term/digital_signature">NIST digital signatures</a>.</p></article>`;
}
